// CCH Master Concept Notes — generated from CCH_Latest_Syllabus_Master_Notes.docx
// Covers the full CCH revised syllabus (effective October 2022).

export type NoteBlock = { type: "para" | "bullet"; text: string }
export type NoteTopic = { title: string; blocks: NoteBlock[] }
export type NoteSection = { title: string; topics: NoteTopic[] }

export const MASTER_NOTES_PREAMBLE: NoteBlock[] = [{"type":"para","text":"CCH ENTRY TEST — MASTER CONCEPT NOTES"},{"type":"para","text":"Easy-language notes for Class 8 / O-Level entry preparation"},{"type":"para","text":"Based on the latest CCH revised syllabus supplied: effective October 2022."},{"type":"para","text":"These notes are designed for a student who wants to understand the idea first and then solve questions. They follow the supplied CCH syllabus rather than adding unrelated O-Level material. The CCH Mathematics syllabus specifically describes the entry questions as concept-based and appropriate for Class 7 Cambridge level, and states that calculators, set-squares and protractors are not allowed."},{"type":"para","text":"Best way to use these notesRead the explanation → cover the example → explain the idea aloud in your own words → solve 3–5 questions without looking → return to the 'Common trap' points. If you can explain a concept simply, you probably understand it."}]

export const MASTER_NOTES_SECTIONS: NoteSection[] = [{"title":"1. MATHEMATICS","topics":[{"title":"","blocks":[{"type":"para","text":"The supplied CCH syllabus covers Arithmetic, Sets, Algebra, Mensuration, Geometry/Practical Geometry and Information Handling. The goal is not formula dumping: learn what each idea means and recognise which idea a question is testing."}]},{"title":"1. Numbers and operations","blocks":[{"type":"para","text":"Numbers are the building blocks of almost every Maths question. The real skill is choosing the correct operation and keeping the calculation organised."},{"type":"bullet","text":"Place value tells you what each digit is worth."},{"type":"bullet","text":"Factors divide a number exactly; multiples are produced by multiplying."},{"type":"bullet","text":"A prime number has exactly two positive factors: 1 and itself."},{"type":"bullet","text":"HCF is the largest factor shared by numbers. LCM is the smallest positive multiple shared by them."},{"type":"bullet","text":"Estimate before calculating. If your exact answer is very far from the estimate, check your work."},{"type":"bullet","text":"For negative numbers, think of a number line: adding a negative moves left; subtracting a negative moves right."},{"type":"para","text":"Think like this:For 18 and 24, the HCF is 6 because 6 is the largest number dividing both exactly. The LCM is 72 because 72 is the smallest positive number that both 18 and 24 divide exactly."}]},{"title":"2. Fractions","blocks":[{"type":"para","text":"A fraction is a division written in a compact form. The denominator tells how many equal parts make one whole; the numerator tells how many parts are being considered."},{"type":"bullet","text":"Simplify by dividing the top and bottom by the same non-zero factor."},{"type":"bullet","text":"For addition/subtraction, make the denominators compatible first."},{"type":"bullet","text":"For multiplication, multiply numerator by numerator and denominator by denominator."},{"type":"bullet","text":"For division, multiply by the reciprocal of the second fraction."},{"type":"bullet","text":"A mixed number can be converted to an improper fraction before calculation."},{"type":"para","text":"Think like this:To add 1/3 + 1/6, change 1/3 to 2/6. Then 2/6 + 1/6 = 3/6 = 1/2."}]},{"title":"3. Ratio and proportion","blocks":[{"type":"para","text":"Ratio compares quantities. Proportion means two ratios are equal."},{"type":"bullet","text":"A ratio 2:3 has 5 total parts."},{"type":"bullet","text":"To divide 40 in the ratio 3:5, first find one part: 40 ÷ 8 = 5. Then the amounts are 15 and 25."},{"type":"bullet","text":"Never compare unlike units without converting them first."},{"type":"bullet","text":"Equivalent ratios are made by multiplying or dividing every part by the same number."},{"type":"para","text":"Think like this:If boys:girls = 4:5 and there are 36 students, there are 9 total parts, so each part is 4. Boys = 16 and girls = 20."}]},{"title":"4. Percentage","blocks":[{"type":"para","text":"Percent means 'out of 100'. Most percentage questions become easy once you identify the original quantity and what the percentage is being taken of."},{"type":"bullet","text":"x% of a quantity = x/100 × quantity."},{"type":"bullet","text":"Percentage change = change ÷ original × 100."},{"type":"bullet","text":"For a discount, subtract the discount from the marked price."},{"type":"bullet","text":"For profit, profit = selling price − cost price."},{"type":"bullet","text":"For loss, loss = cost price − selling price."},{"type":"bullet","text":"Tax/percentage increase is applied to the stated base; read the wording carefully."},{"type":"para","text":"Think like this:15% of Rs 800 = 15/100 × 800 = Rs 120. A price reduced by 15% therefore becomes Rs 680."}]},{"title":"5. Direct and inverse variation","blocks":[{"type":"para","text":"Variation describes how two quantities change together."},{"type":"bullet","text":"Direct: both quantities change in the same direction in a fixed proportion."},{"type":"bullet","text":"Inverse: one increases while the other decreases so their product remains constant."},{"type":"bullet","text":"In worker/day problems, more workers generally mean fewer days if everyone works equally and the amount of work is unchanged."},{"type":"para","text":"Think like this:If 6 workers need 10 days, an inverse-variation model gives 6×10 = 60 worker-days. With 12 workers, 60÷12 = 5 days."}]},{"title":"6. Time, distance and speed","blocks":[{"type":"para","text":"These questions are really about the relationship between three quantities."},{"type":"bullet","text":"Speed = distance ÷ time."},{"type":"bullet","text":"Distance = speed × time."},{"type":"bullet","text":"Time = distance ÷ speed."},{"type":"bullet","text":"Convert time to a consistent unit before calculating."},{"type":"bullet","text":"For 2 h 30 min, use 2.5 h when speed is in km/h."},{"type":"para","text":"Think like this:A car travels 150 km in 3 h. Speed = 150 ÷ 3 = 50 km/h."}]},{"title":"7. Sets","blocks":[{"type":"para","text":"A set is a collection of objects with a clear membership rule. Venn diagrams make relationships between sets easier to see."},{"type":"bullet","text":"Union A∪B means everything in A or B or both."},{"type":"bullet","text":"Intersection A∩B means items common to both."},{"type":"bullet","text":"Difference A−B means items in A but not in B."},{"type":"bullet","text":"Complement means items outside the set, within the stated universal set."},{"type":"bullet","text":"For two sets: n(A∪B)=n(A)+n(B)−n(A∩B)."},{"type":"para","text":"Think like this:If 20 students like cricket, 15 like football and 5 like both, at least one = 20+15−5 = 30."}]},{"title":"8. Algebraic expressions and equations","blocks":[{"type":"para","text":"An expression has numbers, variables and operations but no equals sign. An equation says two expressions are equal."},{"type":"bullet","text":"A variable is a symbol representing a number."},{"type":"bullet","text":"Like terms can be combined: 3x+2x = 5x."},{"type":"bullet","text":"Substitution means replacing a variable with its given value."},{"type":"bullet","text":"To solve an equation, do the same operation to both sides."},{"type":"bullet","text":"Translate words carefully: '5 more than x' is x+5, while '5 times x' is 5x."},{"type":"para","text":"Think like this:If 3x+4=19, subtract 4 from both sides: 3x=15, then divide by 3: x=5."}]},{"title":"9. Algebraic fractions and exponents","blocks":[{"type":"para","text":"Algebraic fractions follow the same basic fraction rules, while exponents show repeated multiplication."},{"type":"bullet","text":"x² means x×x; x³ means x×x×x."},{"type":"bullet","text":"When multiplying powers with the same base, add exponents: x²×x³=x⁵."},{"type":"bullet","text":"When dividing powers with the same base, subtract exponents: x⁵÷x²=x³."},{"type":"bullet","text":"Do not cancel terms across addition: (x+2)/x is not 1+2/x by 'cancelling' x incorrectly."},{"type":"para","text":"Think like this:For x=3, 2x² = 2×9 = 18."}]},{"title":"10. Linear graphs","blocks":[{"type":"para","text":"A linear graph shows a constant rate of change and forms a straight line."},{"type":"bullet","text":"Make a table of x and y values when needed."},{"type":"bullet","text":"Plot points carefully and join them with a straight line when the relationship is linear."},{"type":"bullet","text":"The horizontal axis is usually x; the vertical axis is usually y."},{"type":"bullet","text":"Read values from the graph using the scale, not by guessing the visual position."},{"type":"para","text":"Think like this:For y=2x+1, x=0 gives y=1, x=1 gives y=3, and x=2 gives y=5. These points lie on a straight line."}]},{"title":"11. Mensuration","blocks":[{"type":"para","text":"Mensuration is measurement of length, perimeter, area, surface area and volume."},{"type":"bullet","text":"Rectangle: area = length×width; perimeter = 2(length+width)."},{"type":"bullet","text":"Triangle: area = 1/2×base×height."},{"type":"bullet","text":"For a prism, volume = area of cross-section × length."},{"type":"bullet","text":"Keep square units for area and cubic units for volume."},{"type":"bullet","text":"Break complicated shapes into familiar shapes rather than trying to invent a new formula."},{"type":"para","text":"Think like this:A 10 m by 4 m rectangle has area 40 m² and perimeter 28 m."}]},{"title":"12. Similar figures","blocks":[{"type":"para","text":"Similar figures have the same shape but may have different sizes. Corresponding lengths are in the same ratio."},{"type":"bullet","text":"If the length scale factor is k, areas scale by k²."},{"type":"bullet","text":"Match corresponding sides before calculating."},{"type":"bullet","text":"Do not use the same scale factor for area unless k=1."},{"type":"para","text":"Think like this:If a shape is enlarged by scale factor 2, every length doubles but its area becomes 4 times as large."}]},{"title":"13. Pythagoras' theorem","blocks":[{"type":"para","text":"In a right-angled triangle, the square of the longest side equals the sum of the squares of the other two sides."},{"type":"bullet","text":"Only use the theorem for a right-angled triangle."},{"type":"bullet","text":"The hypotenuse is always opposite the right angle and is the longest side."},{"type":"bullet","text":"a²+b²=c²."},{"type":"bullet","text":"If finding a shorter side, rearrange: a²=c²−b²."},{"type":"para","text":"Think like this:A right triangle with legs 5 and 12 has hypotenuse √(25+144)=13."}]},{"title":"14. Polygons and angles","blocks":[{"type":"para","text":"A polygon is a closed plane shape made from straight line segments."},{"type":"bullet","text":"Interior-angle sum of an n-sided polygon = (n−2)×180°."},{"type":"bullet","text":"The exterior angles of a polygon add to 360°."},{"type":"bullet","text":"For a regular polygon, all sides and angles are equal."},{"type":"bullet","text":"A regular polygon's exterior angle = 360° ÷ number of sides."},{"type":"para","text":"Think like this:A pentagon has interior-angle sum (5−2)×180° = 540°."}]},{"title":"15. Geometry: angle relationships","blocks":[{"type":"para","text":"Many geometry questions are solved by spotting standard angle relationships."},{"type":"bullet","text":"Angles on a straight line add to 180°."},{"type":"bullet","text":"Angles around a point add to 360°."},{"type":"bullet","text":"Vertically opposite angles are equal."},{"type":"bullet","text":"For parallel lines, alternate angles are equal and corresponding angles are equal."},{"type":"bullet","text":"Triangle angles add to 180°."},{"type":"para","text":"Think like this:If two parallel lines are cut by a transversal and one corresponding angle is 65°, the matching corresponding angle is also 65°."}]},{"title":"16. Circle vocabulary","blocks":[{"type":"para","text":"Know the parts of a circle because CCH can test recognition and relationships."},{"type":"bullet","text":"Radius: centre to circumference."},{"type":"bullet","text":"Diameter: chord through the centre; it is twice the radius."},{"type":"bullet","text":"Chord: line segment joining two points on the circle."},{"type":"bullet","text":"Arc: part of the circumference."},{"type":"bullet","text":"Tangent: line touching a circle at one point."},{"type":"bullet","text":"Sector: region bounded by two radii and an arc."},{"type":"para","text":"Think like this:If radius = 7 cm, diameter = 14 cm."}]},{"title":"17. Cyclic quadrilaterals","blocks":[{"type":"para","text":"A cyclic quadrilateral has all four vertices on a circle."},{"type":"bullet","text":"Opposite angles of a cyclic quadrilateral add to 180°."},{"type":"bullet","text":"If one opposite angle is 110°, the other is 70°."},{"type":"bullet","text":"Look for the word 'cyclic' or a clear circle passing through all four vertices."},{"type":"para","text":"Think like this:If angle A is 82° in a cyclic quadrilateral, the opposite angle is 98°."}]},{"title":"18. Transformations","blocks":[{"type":"para","text":"A transformation moves or changes a shape while following a precise rule."},{"type":"bullet","text":"Reflection flips a shape across a mirror line."},{"type":"bullet","text":"The line of reflection is halfway between a point and its image and is perpendicular to the joining segment."},{"type":"bullet","text":"Translation moves every point the same distance in the same direction."},{"type":"bullet","text":"A translation can be described using horizontal and vertical movement."},{"type":"para","text":"Think like this:Moving every point 4 squares right and 2 squares up is one translation; the shape does not rotate or change size."}]},{"title":"19. Information handling","blocks":[{"type":"para","text":"Information handling means reading, organising and interpreting data."},{"type":"bullet","text":"Mean = total ÷ number of values."},{"type":"bullet","text":"Median = middle value after arranging data in order."},{"type":"bullet","text":"Mode = most frequent value."},{"type":"bullet","text":"A bar graph compares categories."},{"type":"bullet","text":"A line graph is useful for showing change over an ordered variable such as time."},{"type":"bullet","text":"A pie chart shows parts of a whole; the full circle represents 360°."},{"type":"bullet","text":"Frequency tells how often a value/category occurs."},{"type":"para","text":"Think like this:For 2, 4, 4, 7, 8: mean = 25/5=5, median=4, mode=4."}]},{"title":"20. Probability","blocks":[{"type":"para","text":"Probability measures how likely an event is."},{"type":"bullet","text":"For equally likely outcomes: probability = favourable outcomes ÷ total possible outcomes."},{"type":"bullet","text":"Probability 0 means impossible; probability 1 means certain."},{"type":"bullet","text":"For a simple event, list the possible outcomes before counting."},{"type":"bullet","text":"The probability of an event and its complement add to 1."},{"type":"para","text":"Think like this:A fair die has 6 outcomes. P(rolling an even number)=3/6=1/2."},{"type":"para","text":"Math exam habitUnderline what is being asked, write the useful numbers, choose a method, estimate, calculate, then check units and reasonableness."}]}]},{"title":"2. ENGLISH","topics":[{"title":"","blocks":[{"type":"para","text":"The CCH English syllabus focuses on essay writing, reading comprehension and grammar. The easiest way to improve is to write clearly, read carefully and understand why a grammatical form is correct."}]},{"title":"1. Essay writing: the basic plan","blocks":[{"type":"para","text":"CCH asks candidates to write ONE of TWO topics: one narrative and one descriptive. Good English is not about using the hardest words; it is about clear ideas, correct grammar, good paragraphing and precise description."},{"type":"bullet","text":"Narrative = events happen; include characters, setting, problem, development and ending."},{"type":"bullet","text":"Descriptive = make the reader see/hear/feel the scene; do not turn it into a story."},{"type":"bullet","text":"Use paragraphs. Each paragraph should have a purpose."},{"type":"bullet","text":"Use a mixture of sentence lengths. Short sentences can create impact."},{"type":"bullet","text":"Check spelling, punctuation and verb tense before finishing."},{"type":"para","text":"Think like this:Narrative: 'The lights went out just as we reached the hall.' Then build what happened. Descriptive: instead describe the darkness, sounds, temperature, faces and atmosphere."}]},{"title":"2. Narrative writing","blocks":[{"type":"para","text":"A narrative is a controlled story. The reader should always know who is involved, where they are and what is happening."},{"type":"bullet","text":"Start with an interesting situation rather than a long background explanation."},{"type":"bullet","text":"Use dialogue when it adds information or character."},{"type":"bullet","text":"Keep the tense consistent unless there is a clear reason to change it."},{"type":"bullet","text":"Use sequence words naturally: suddenly, meanwhile, later, eventually."},{"type":"bullet","text":"End with a resolution rather than stopping immediately after the most exciting moment."},{"type":"para","text":"Think like this:Weak: 'I went there. Then this happened. Then that happened.' Stronger writing combines action with thoughts, dialogue and specific detail."}]},{"title":"3. Descriptive writing","blocks":[{"type":"para","text":"Descriptive writing is about creating a picture using language."},{"type":"bullet","text":"Use the five senses: sight, sound, smell, touch and taste where appropriate."},{"type":"bullet","text":"Describe movement, light, weather, distance and atmosphere."},{"type":"bullet","text":"Use specific nouns and strong verbs rather than too many adjectives."},{"type":"bullet","text":"Show feelings through physical details: trembling hands, a forced smile, a racing heartbeat."},{"type":"bullet","text":"Avoid simply listing everything visible."},{"type":"para","text":"Think like this:Instead of 'It was noisy,' try explaining what the reader hears: engines, footsteps, shouted instructions and chairs scraping the floor."}]},{"title":"4. Reading comprehension","blocks":[{"type":"para","text":"CCH expects understanding of explicit information and information that must be inferred from the passage."},{"type":"bullet","text":"Explicit = directly stated."},{"type":"bullet","text":"Inference = a conclusion supported by clues in the passage."},{"type":"bullet","text":"For 'why' questions, give a reason supported by the text."},{"type":"bullet","text":"For vocabulary-in-context, do not automatically use the dictionary meaning; choose the meaning that fits that sentence."},{"type":"bullet","text":"For analytical questions, explain how/why something affects the reader, character or meaning."},{"type":"bullet","text":"Answer in your own words when the question asks for your own words."},{"type":"para","text":"Think like this:If a character keeps checking the clock and tapping their foot, the passage may never say 'she was anxious', but those clues allow that inference."}]},{"title":"5. Grammar: parts of speech","blocks":[{"type":"para","text":"Know what words are doing in a sentence."},{"type":"bullet","text":"Noun = person/place/thing/idea."},{"type":"bullet","text":"Pronoun = replaces a noun."},{"type":"bullet","text":"Verb = action or state."},{"type":"bullet","text":"Adjective = describes a noun."},{"type":"bullet","text":"Adverb = often describes how/when/where an action happens."},{"type":"bullet","text":"Preposition shows a relationship such as in, on, under, between."},{"type":"bullet","text":"Conjunction joins words or ideas."},{"type":"para","text":"Think like this:In 'The extremely tired runner walked slowly to the gate', 'runner' is a noun, 'tired' an adjective, 'walked' a verb and 'slowly' an adverb."}]},{"title":"6. Tenses","blocks":[{"type":"para","text":"Tense tells when an action happens and whether it is complete, continuing or repeated."},{"type":"bullet","text":"Present simple: habits/facts — 'He walks to school.'"},{"type":"bullet","text":"Present continuous: happening now — 'He is walking.'"},{"type":"bullet","text":"Past simple: completed past event — 'He walked yesterday.'"},{"type":"bullet","text":"Past continuous: action in progress in the past — 'He was walking when it rained.'"},{"type":"bullet","text":"Present perfect: past action connected to the present — 'He has finished.'"},{"type":"bullet","text":"Past perfect: an earlier past action — 'He had left before I arrived.'"},{"type":"bullet","text":"Future forms express planned, expected or predicted future events."},{"type":"para","text":"Think like this:Use time clues: 'yesterday' strongly suggests past simple; 'since' or 'already' can signal perfect forms depending on context."}]},{"title":"7. Articles","blocks":[{"type":"para","text":"Articles are small words, but CCH can use them to test precision."},{"type":"bullet","text":"A/an are used for a non-specific singular countable noun."},{"type":"bullet","text":"Use 'an' before a vowel sound, not simply a vowel letter: 'an hour' but 'a university'."},{"type":"bullet","text":"The is used when the noun is specific or already identified."},{"type":"bullet","text":"Plural and uncountable nouns often take no article when speaking generally."},{"type":"para","text":"Think like this:I saw a dog. The dog was carrying a ball. The second mention is specific, so 'the' is natural."}]},{"title":"8. Active and passive voice","blocks":[{"type":"para","text":"Active voice emphasises the doer. Passive voice emphasises the receiver of the action."},{"type":"bullet","text":"Active: 'The boy opened the door.'"},{"type":"bullet","text":"Passive: 'The door was opened by the boy.'"},{"type":"bullet","text":"Keep the tense when changing voice."},{"type":"bullet","text":"Only verbs that take an object can normally be changed into passive voice."},{"type":"para","text":"Think like this:Present: 'They clean the room.' → 'The room is cleaned by them.' Past: 'They cleaned the room.' → 'The room was cleaned by them.'"}]},{"title":"9. Direct and reported speech","blocks":[{"type":"para","text":"Direct speech gives the exact words; reported speech tells what someone said."},{"type":"bullet","text":"Adjust pronouns when the speaker changes."},{"type":"bullet","text":"Often move the tense back when the reporting verb is in the past."},{"type":"bullet","text":"Change time/place expressions when necessary: today → that day, tomorrow → the next day, here → there."},{"type":"bullet","text":"Questions become statement word order in reported speech."},{"type":"para","text":"Think like this:Direct: Ali said, 'I am tired.' Reported: Ali said that he was tired."}]},{"title":"10. Punctuation and spelling","blocks":[{"type":"para","text":"Punctuation helps the reader understand the structure and meaning of your writing."},{"type":"bullet","text":"Capitalise sentence beginnings and proper nouns."},{"type":"bullet","text":"Use full stops for complete statements."},{"type":"bullet","text":"Use commas to separate items and help organise clauses."},{"type":"bullet","text":"Use apostrophes for possession and contractions."},{"type":"bullet","text":"Use quotation marks for direct speech where required by the expected style."},{"type":"bullet","text":"Check commonly confused spellings."},{"type":"para","text":"Think like this:Compare 'Let's eat, Ali' with 'Let's eat Ali.' The comma can completely change the meaning."}]},{"title":"11. Prepositions and pairs of words","blocks":[{"type":"para","text":"Prepositions are often tested through context. Pairs of words test whether you know similar-looking words with different meanings."},{"type":"bullet","text":"Learn phrases in context: interested in, good at, afraid of."},{"type":"bullet","text":"Check the exact meaning before choosing between similar words."},{"type":"bullet","text":"Do not choose a word only because it 'sounds right'."},{"type":"para","text":"Think like this:Advice = a noun; advise = a verb. Their meanings are related, but their jobs in a sentence differ."},{"type":"para","text":"English exam habitFor comprehension, answer from the passage. For grammar, read the whole sentence before choosing. For essays, spend a few minutes planning before writing."}]}]},{"title":"3. اردو","topics":[{"title":"","blocks":[{"type":"para","text":"اردو کے نوٹس CCH کے فراہم کردہ syllabus کے مطابق مضمون نگاری، فہم، شعر کی تشریح، قواعد، محاورات/ضرب الامثال، جملوں کی تبدیلی، خلاصہ اور ہم آواز الفاظ پر توجہ دیتے ہیں۔"}]},{"title":"1. مضمون نگاری","blocks":[{"type":"para","text":"CCH expects a coherent, relevant Urdu essay on a range of educational, social, historical, analytical, personal or event-based topics."},{"type":"bullet","text":"Start with a short introduction."},{"type":"bullet","text":"Develop 3–5 clear ideas in separate paragraphs."},{"type":"bullet","text":"Use examples where useful."},{"type":"bullet","text":"Keep the language natural and correct rather than unnecessarily difficult."},{"type":"bullet","text":"Finish with a conclusion that brings the main idea together."},{"type":"para","text":"Think like this:موضوع 'وقت کی پابندی' ہو تو صرف وقت کی تعریف نہ کریں: طالب علم، تعلیم، روزمرہ زندگی، کامیابی اور عملی مثالوں سے موضوع کو develop کریں۔"}]},{"title":"2. فہمِ عبارت","blocks":[{"type":"para","text":"عبارت کو صرف پڑھنا کافی نہیں؛ اس کا مرکزی خیال، تفصیل، الفاظ اور مصنف کی بات سمجھنا ضروری ہے۔"},{"type":"bullet","text":"پہلے پوری عبارت کا عمومی مطلب سمجھیں۔"},{"type":"bullet","text":"سوال کا جواب عبارت کے مطابق دیں، اپنی غیر متعلقہ رائے نہ شامل کریں۔"},{"type":"bullet","text":"اگر اپنے الفاظ میں جواب مانگا جائے تو عبارت کی نقل نہ کریں۔"},{"type":"bullet","text":"محاورے کا مطلب سیاق و سباق سے سمجھیں۔"},{"type":"bullet","text":"مشکل لفظ کا معنی پورے جملے کو دیکھ کر اخذ کریں۔"},{"type":"para","text":"Think like this:اگر عبارت میں کسی شخص کے بار بار کوشش کرنے اور ناکامی کے باوجود دوبارہ کام شروع کرنے کا ذکر ہو تو اس سے ثابت قدمی کا مفہوم اخذ کیا جا سکتا ہے۔"}]},{"title":"3. اسم، فعل، حرف اور بنیادی قواعد","blocks":[{"type":"para","text":"قواعد میں یہ پہچاننا ضروری ہے کہ جملے میں لفظ کا کام کیا ہے۔"},{"type":"bullet","text":"اسم: شخص، جگہ، چیز یا تصور کا نام۔"},{"type":"bullet","text":"فعل: کام یا حالت ظاہر کرتا ہے۔"},{"type":"bullet","text":"حرف: الفاظ یا جملوں کے درمیان تعلق قائم کرتا ہے۔"},{"type":"bullet","text":"جملے کے سیاق کے مطابق لفظ کی نحوی حیثیت پہچانیں۔"},{"type":"para","text":"Think like this:جملہ: 'علی کتاب پڑھتا ہے۔' علی اور کتاب اسم ہیں، 'پڑھتا ہے' فعل ہے۔"}]},{"title":"4. واحد اور جمع","blocks":[{"type":"para","text":"واحد ایک اور جمع ایک سے زیادہ کے لیے استعمال ہوتی ہے۔ ہر لفظ کی جمع صرف 'ات' یا 'یں' لگانے سے نہیں بنتی۔"},{"type":"bullet","text":"عام اور غیر معمولی جمعوں کو مثالوں کے ساتھ یاد کریں۔"},{"type":"bullet","text":"جملے میں واحد/جمع کی مطابقت بھی دیکھیں۔"},{"type":"bullet","text":"املا پر خاص توجہ دیں۔"},{"type":"para","text":"Think like this:لفظ کو صرف الگ سے یاد نہ کریں؛ اسے جملے میں استعمال کر کے یاد کریں۔"}]},{"title":"5. مترادف اور متضاد","blocks":[{"type":"para","text":"مترادف ایسے الفاظ ہیں جن کے معنی قریب ہوں؛ متضاد الفاظ کے معنی ایک دوسرے کے مخالف ہوں۔"},{"type":"bullet","text":"مترادف کا مطلب مکمل طور پر ایک جیسا ہونا ضروری نہیں؛ سیاق اہم ہے۔"},{"type":"bullet","text":"متضاد میں درست جوڑا بنانا ضروری ہے۔"},{"type":"bullet","text":"الفاظ کو جملوں میں استعمال کر کے فرق سمجھیں۔"},{"type":"para","text":"Think like this:خوش کا مترادف شاد/مسرت آمیز سیاق کے مطابق ہو سکتا ہے؛ خوش کا متضاد غمگین ہے۔"}]},{"title":"6. محاورات اور ضرب الامثال","blocks":[{"type":"para","text":"محاورہ ایسا مقررہ فقرہ ہے جس کا مفہوم اکثر لفظی معنی سے مختلف ہوتا ہے۔ ضرب المثل ایک معروف دانائی یا تجربے پر مبنی کہاوت ہوتی ہے۔"},{"type":"bullet","text":"محاورے کا مطلب سمجھیں۔"},{"type":"bullet","text":"اسے مناسب جملے میں استعمال کریں۔"},{"type":"bullet","text":"صرف محاورہ لکھنا کافی نہیں اگر سوال جملہ مانگے۔"},{"type":"bullet","text":"سیاق کے مطابق محاورہ منتخب کریں۔"},{"type":"para","text":"Think like this:اگر کسی شخص کی اچانک بہت زیادہ تعریف ہو تو مناسب محاورہ چننے سے پہلے دیکھیں کہ سوال تعریف، خوشی، مشکل یا حیرت میں سے کس مفہوم کی طرف جا رہا ہے۔"}]},{"title":"7. جملوں کی تبدیلی","blocks":[{"type":"para","text":"CCH میں خبریہ، سوالیہ، منفی اور امریہ جملوں کی تبدیلی آ سکتی ہے۔"},{"type":"bullet","text":"خبریہ: خبر یا بیان دیتا ہے۔"},{"type":"bullet","text":"سوالیہ: سوال پوچھتا ہے۔"},{"type":"bullet","text":"منفی: نفی ظاہر کرتا ہے۔"},{"type":"bullet","text":"امریہ: حکم، درخواست یا ہدایت دے سکتا ہے۔"},{"type":"bullet","text":"تبدیلی کرتے وقت اصل مفہوم کو زیادہ سے زیادہ برقرار رکھیں۔"},{"type":"para","text":"Think like this:خبریہ: 'وہ آج آئے گا۔' منفی: 'وہ آج نہیں آئے گا۔' سوالیہ: 'کیا وہ آج آئے گا؟'"}]},{"title":"8. غلط عبارت کی اصلاح","blocks":[{"type":"para","text":"غلط عبارت میں املا، قواعد، فعل، واحد/جمع یا جملے کی ساخت کی غلطیاں ہو سکتی ہیں۔"},{"type":"bullet","text":"ایک ایک جملہ الگ پڑھیں۔"},{"type":"bullet","text":"پہلے واضح املا کی غلطی دیکھیں۔"},{"type":"bullet","text":"پھر فعل اور اسم کی مطابقت دیکھیں۔"},{"type":"bullet","text":"آخر میں جملے کا پورا مفہوم پڑھیں۔"},{"type":"para","text":"Think like this:صرف ایک لفظ دیکھ کر فیصلہ نہ کریں؛ پورا جملہ دیکھیں کیونکہ بعض الفاظ سیاق کے بدلنے سے مختلف صورت اختیار کرتے ہیں۔"}]},{"title":"9. خلاصہ نویسی","blocks":[{"type":"para","text":"خلاصہ اصل عبارت کی مرکزی باتوں کو مختصر، مربوط اور اپنے الفاظ میں بیان کرنا ہے۔"},{"type":"bullet","text":"غیر ضروری مثالیں اور تکرار نکال دیں۔"},{"type":"bullet","text":"مرکزی خیال اور اہم نکات رکھیں۔"},{"type":"bullet","text":"اپنی نئی رائے شامل نہ کریں۔"},{"type":"bullet","text":"جملوں میں ربط رکھیں۔"},{"type":"para","text":"Think like this:ہر جملہ اٹھا کر چھوٹا کرنا خلاصہ نہیں؛ پہلے عبارت کی اصل بات سمجھیں، پھر اسے مختصر انداز میں دوبارہ بیان کریں۔"}]},{"title":"10. ہم آواز الفاظ","blocks":[{"type":"para","text":"ہم آواز الفاظ سننے میں ملتے جلتے ہو سکتے ہیں مگر ان کے معنی یا املا مختلف ہو سکتے ہیں۔"},{"type":"bullet","text":"لفظ کا معنی اور املا دونوں یاد کریں۔"},{"type":"bullet","text":"جملے میں استعمال کر کے فرق مضبوط کریں۔"},{"type":"bullet","text":"صرف آواز پر بھروسا نہ کریں۔"},{"type":"para","text":"Think like this:دو ہم آواز الفاظ کا فرق سمجھنے کے لیے دونوں کو الگ الگ جملوں میں استعمال کرنا بہترین طریقہ ہے۔"},{"type":"para","text":"اردو امتحانی عادتسوال پہلے سمجھیں، پھر جواب لکھیں۔ مضمون میں پیراگراف اور ربط رکھیں؛ قواعد میں صرف اندازہ نہ لگائیں بلکہ جملے کا پورا مفہوم دیکھیں۔"}]}]},{"title":"4. GENERAL SCIENCE","topics":[{"title":"","blocks":[{"type":"para","text":"The CCH General Science syllabus is deliberately interdisciplinary: Biology, Chemistry and Physics concepts are tested through MCQs and applications. The aim is a strong pre-secondary science foundation, so these notes explain the core ideas without jumping into unnecessary O-Level detail."}]},{"title":"1. Cell — basic unit of life","blocks":[{"type":"para","text":"A cell is the basic structural and functional unit of living things. Different cells are specialised for different jobs."},{"type":"bullet","text":"Cell membrane controls what enters and leaves the cell."},{"type":"bullet","text":"Cytoplasm is where many chemical reactions occur."},{"type":"bullet","text":"Nucleus contains genetic information and helps control cell activities."},{"type":"bullet","text":"Plant cells also have a cell wall, chloroplasts and a large permanent vacuole."},{"type":"bullet","text":"Animal cells do not have a cell wall or chloroplasts."},{"type":"para","text":"Think like this:A plant cell needs chloroplasts to capture light energy for photosynthesis, while an animal cell does not make food this way."}]},{"title":"2. Human digestive system","blocks":[{"type":"para","text":"Digestion breaks large food molecules into smaller substances that can be absorbed and used."},{"type":"bullet","text":"Mouth: chewing and saliva begin digestion."},{"type":"bullet","text":"Oesophagus moves food to the stomach."},{"type":"bullet","text":"Stomach churns food and uses digestive juices."},{"type":"bullet","text":"Small intestine completes much digestion and absorbs soluble nutrients."},{"type":"bullet","text":"Large intestine absorbs much of the remaining water."},{"type":"bullet","text":"The liver produces bile; bile helps fats break into smaller droplets. The pancreas supplies digestive enzymes."},{"type":"para","text":"Think like this:Digestion is not the same as absorption. Digestion breaks food down; absorption moves useful soluble substances into the body."}]},{"title":"3. Transport systems in living things","blocks":[{"type":"para","text":"Organisms need substances to move from where they are obtained or produced to where they are needed."},{"type":"bullet","text":"Humans use blood vessels and the circulatory system to transport oxygen, nutrients, hormones and wastes."},{"type":"bullet","text":"Red blood cells carry oxygen using haemoglobin."},{"type":"bullet","text":"Plants use xylem to transport water and mineral ions and phloem to transport dissolved food such as sugars."},{"type":"bullet","text":"Diffusion is movement from higher concentration to lower concentration."},{"type":"para","text":"Think like this:A leaf makes sugars by photosynthesis; transport tissues help move materials to other parts of the plant."}]},{"title":"4. Reproduction in plants","blocks":[{"type":"para","text":"Plants can reproduce sexually using flowers and seeds, and many plants can also reproduce asexually."},{"type":"bullet","text":"Pollination is transfer of pollen from anther to stigma."},{"type":"bullet","text":"Fertilisation is the fusion of male and female gametes."},{"type":"bullet","text":"After fertilisation, the ovule develops into a seed and the ovary develops into a fruit in flowering plants."},{"type":"bullet","text":"Seeds contain a young plant and stored food."},{"type":"para","text":"Think like this:Pollination happens before fertilisation. They are not the same event."}]},{"title":"5. Environment and feeding relationships","blocks":[{"type":"para","text":"Living things interact with each other and with non-living parts of their environment."},{"type":"bullet","text":"A habitat provides the conditions and resources an organism needs."},{"type":"bullet","text":"A food chain shows feeding relationships and the transfer of energy."},{"type":"bullet","text":"Plants are producers because they make food."},{"type":"bullet","text":"Herbivores eat plants; carnivores eat animals; omnivores eat both."},{"type":"bullet","text":"A food web combines many connected food chains."},{"type":"bullet","text":"Changes to one population can affect other populations."},{"type":"para","text":"Think like this:If the number of plants falls, herbivores may have less food, which can then affect predators that depend on those herbivores."}]},{"title":"6. Particulate nature of matter","blocks":[{"type":"para","text":"Matter is made of tiny particles. The arrangement and movement of particles help explain the behaviour of solids, liquids and gases."},{"type":"bullet","text":"Solid particles are closely packed and mainly vibrate in fixed positions."},{"type":"bullet","text":"Liquid particles remain close but can move past one another."},{"type":"bullet","text":"Gas particles are far apart and move freely."},{"type":"bullet","text":"Heating generally increases particle movement."},{"type":"bullet","text":"Diffusion is faster in gases than in liquids because particles move more freely."},{"type":"para","text":"Think like this:A gas fills its container because its particles move in many directions and spread out."}]},{"title":"7. Atoms and molecules","blocks":[{"type":"para","text":"An atom is a basic particle of an element. Molecules are groups of atoms joined together."},{"type":"bullet","text":"Elements contain one type of atom."},{"type":"bullet","text":"A molecule may contain atoms of the same element, such as oxygen molecules, or atoms of different elements."},{"type":"bullet","text":"Atoms are far too small to see directly with ordinary classroom equipment."},{"type":"bullet","text":"Chemical symbols are shorthand for elements."},{"type":"para","text":"Think like this:Water is made of hydrogen and oxygen atoms chemically joined in molecules."}]},{"title":"8. Chemical composition and diversity of matter","blocks":[{"type":"para","text":"Different substances have different properties because their particles and chemical compositions are different."},{"type":"bullet","text":"Element = one type of atom."},{"type":"bullet","text":"Compound = different elements chemically combined."},{"type":"bullet","text":"Mixture = substances together without being chemically joined."},{"type":"bullet","text":"Mixtures can often be separated by physical methods."},{"type":"bullet","text":"A compound has properties different from the elements that formed it."},{"type":"para","text":"Think like this:Salt water is a mixture; sodium chloride is a compound."}]},{"title":"9. Chemical changes","blocks":[{"type":"para","text":"A chemical change produces one or more new substances."},{"type":"bullet","text":"Signs may include gas production, colour change, temperature change, light or formation of a precipitate."},{"type":"bullet","text":"Chemical changes are usually difficult to reverse by simple physical methods."},{"type":"bullet","text":"Combustion is a chemical reaction involving oxygen."},{"type":"bullet","text":"Rusting is a chemical change involving iron, oxygen and water/moisture."},{"type":"para","text":"Think like this:Melting ice changes state but remains water, so it is a physical change. Burning paper creates new substances, so it is chemical."}]},{"title":"10. Physical properties","blocks":[{"type":"para","text":"Physical properties can be observed or measured without changing a substance into a new substance."},{"type":"bullet","text":"State, colour, density, melting point, boiling point and electrical conductivity are examples."},{"type":"bullet","text":"Solubility tells how well a substance dissolves in a particular solvent under stated conditions."},{"type":"bullet","text":"Changes of state are physical changes."},{"type":"para","text":"Think like this:Ice, liquid water and water vapour are different states of the same substance."}]},{"title":"11. Forces and transfer of energy","blocks":[{"type":"para","text":"A force is a push or pull. Forces can change motion or shape."},{"type":"bullet","text":"Balanced forces do not produce a change in motion."},{"type":"bullet","text":"An unbalanced force can speed up, slow down or change direction."},{"type":"bullet","text":"Friction opposes motion between surfaces."},{"type":"bullet","text":"Gravity pulls objects toward Earth."},{"type":"bullet","text":"Energy can be transferred between objects and can change form."},{"type":"para","text":"Think like this:A stationary football begins moving when an unbalanced force from a kick acts on it."}]},{"title":"12. Heat energy and its effects","blocks":[{"type":"para","text":"Heating transfers energy to a substance and can change its temperature, state or size."},{"type":"bullet","text":"Solids, liquids and gases can expand when heated."},{"type":"bullet","text":"Conduction transfers thermal energy through direct particle interactions, especially in solids."},{"type":"bullet","text":"Convection involves movement of fluids such as liquids and gases."},{"type":"bullet","text":"Radiation can transfer thermal energy without a material medium."},{"type":"bullet","text":"Heating can cause melting, evaporation or boiling depending on the substance and conditions."},{"type":"para","text":"Think like this:A metal spoon in hot tea becomes warm mainly because thermal energy is conducted through the spoon."}]},{"title":"13. Sound and light","blocks":[{"type":"para","text":"Sound and light are forms of energy that behave differently."},{"type":"bullet","text":"Sound is produced by vibrations and needs a medium to travel."},{"type":"bullet","text":"Pitch is related to frequency; louder sound is associated with greater amplitude."},{"type":"bullet","text":"Light can travel through a vacuum."},{"type":"bullet","text":"Reflection is bouncing from a surface."},{"type":"bullet","text":"Refraction is bending caused by a change in speed as light enters a different medium."},{"type":"bullet","text":"Transparent materials transmit much light; opaque materials block most light."},{"type":"para","text":"Think like this:A high-pitched sound has a higher frequency than a low-pitched sound."}]},{"title":"14. Earth, space and oceans","blocks":[{"type":"para","text":"Earth is a planet with land, water, air and living systems. Oceans cover most of Earth's surface and influence weather and climate."},{"type":"bullet","text":"Day and night are caused by Earth's rotation."},{"type":"bullet","text":"Earth's atmosphere contains gases important for life and weather."},{"type":"bullet","text":"The ocean is a major part of Earth's water system."},{"type":"bullet","text":"The Sun provides most of the energy driving Earth's surface systems."},{"type":"bullet","text":"Know the difference between weather (short-term atmospheric conditions) and climate (longer-term patterns)."},{"type":"para","text":"Think like this:It is daytime on the side of Earth facing the Sun and night on the side facing away from it."}]},{"title":"15. Solar system","blocks":[{"type":"para","text":"The Solar System consists of the Sun and objects that orbit it, including planets, moons, asteroids and comets."},{"type":"bullet","text":"The Sun is a star at the centre of our Solar System."},{"type":"bullet","text":"The eight planets orbit the Sun."},{"type":"bullet","text":"A planet does not produce its own light like a star; it reflects light."},{"type":"bullet","text":"Moons orbit planets."},{"type":"bullet","text":"Asteroids are rocky objects; comets contain ice, dust and rock and can develop tails when near the Sun."},{"type":"para","text":"Think like this:Earth's seasons are not caused simply by being closer to the Sun; Earth's tilted axis and its orbit around the Sun are important."},{"type":"para","text":"Science exam habitDo not memorise only definitions. Ask: What causes it? What changes? What stays the same? What would happen if one condition changed? Those questions turn facts into understanding."}]}]},{"title":"5. ISLAMIAT","topics":[{"title":"","blocks":[{"type":"para","text":"The supplied CCH Islamiat syllabus is focused on the life of the Prophet ﷺ and the significance of major events and qualities. The assessment objectives specifically ask students to recall relevant facts and demonstrate their significance in Islamic teachings and Muslim life."}]},{"title":"1. First revelation","blocks":[{"type":"para","text":"The first revelation marks the beginning of the Prophethood of Muhammad ﷺ. The event took place in the Cave of Hira, where the first verses of Surah Al-'Alaq were revealed through Angel Jibril عليه السلام."},{"type":"bullet","text":"Understand the setting and sequence of the event."},{"type":"bullet","text":"Know the significance of revelation beginning the mission of Prophethood."},{"type":"bullet","text":"The event teaches reflection, responsibility and obedience to Allah."},{"type":"para","text":"Think like this:Remember the difference between the event itself and the lessons drawn from it. CCH may ask either."}]},{"title":"2. Persecution by the Quraysh","blocks":[{"type":"para","text":"When the Prophet ﷺ called people towards Islam, the Quraysh opposed the message and persecuted Muslims."},{"type":"bullet","text":"Know why the Quraysh opposed the message: it challenged their beliefs and social practices."},{"type":"bullet","text":"Understand the patience and steadfastness shown by the Prophet ﷺ and early Muslims."},{"type":"bullet","text":"Focus on lessons of courage, patience and trust in Allah."},{"type":"para","text":"Think like this:An application question may ask how a student can show patience when facing pressure or unfair treatment."}]},{"title":"3. Migration to Madinah","blocks":[{"type":"para","text":"The Hijrah was the migration of the Prophet ﷺ and Muslims from Makkah to Madinah."},{"type":"bullet","text":"Know why migration became necessary because of persecution and the difficult situation in Makkah."},{"type":"bullet","text":"Understand its importance in establishing the Muslim community in Madinah."},{"type":"bullet","text":"Recognise the importance of planning, trust in Allah and sacrifice."},{"type":"para","text":"Think like this:The key idea is not simply 'moving from one city to another'; it was a major turning point for the Muslim community."}]},{"title":"4. Battle of Badr","blocks":[{"type":"para","text":"Badr was an important early battle in Islamic history. Understanding its significance is more useful than memorising isolated facts."},{"type":"bullet","text":"Know its place in the early Madinan period."},{"type":"bullet","text":"Understand the importance of faith, courage and preparation."},{"type":"bullet","text":"Connect the event with reliance on Allah while still taking practical means."},{"type":"para","text":"Think like this:A good answer links faith with action rather than treating them as opposites."}]},{"title":"5. Battle of Uhud","blocks":[{"type":"para","text":"Uhud teaches important lessons about obedience, discipline, leadership and the consequences of not following instructions."},{"type":"bullet","text":"Understand that the battle involved difficult circumstances for the Muslims."},{"type":"bullet","text":"Pay attention to the lesson of obeying the Prophet's ﷺ instructions."},{"type":"bullet","text":"Learn that a temporary setback does not mean giving up."},{"type":"para","text":"Think like this:For an application question, connect discipline at Uhud to following instructions in school, training or teamwork."}]},{"title":"6. Battle of the Trench","blocks":[{"type":"para","text":"The Battle of the Trench shows strategic thinking and collective effort in defending Madinah."},{"type":"bullet","text":"Understand the defensive strategy used to protect the city."},{"type":"bullet","text":"Recognise the value of consultation, planning and teamwork."},{"type":"bullet","text":"Relate hardship and fear to patience and perseverance."},{"type":"para","text":"Think like this:A useful lesson: courage does not mean having no fear; it can mean continuing to act wisely despite difficulty."}]},{"title":"7. Treaty of Hudaibiyah","blocks":[{"type":"para","text":"Hudaibiyah was an important treaty that required patience and wisdom. Its benefits became clearer over time."},{"type":"bullet","text":"Understand the importance of fulfilling agreements."},{"type":"bullet","text":"Recognise the value of peace and strategic patience."},{"type":"bullet","text":"Learn that an outcome that looks difficult at first can have long-term benefits."},{"type":"para","text":"Think like this:In an application answer, show how patience can prevent a short-term reaction from damaging a long-term goal."}]},{"title":"8. Conquest of Makkah","blocks":[{"type":"para","text":"The conquest of Makkah is strongly connected with mercy, forgiveness and restraint after the Muslims gained power."},{"type":"bullet","text":"Understand that victory did not become an excuse for revenge."},{"type":"bullet","text":"Focus on forgiveness and mercy."},{"type":"bullet","text":"Connect the Prophet's ﷺ conduct to moral leadership."},{"type":"para","text":"Think like this:A strong answer explains why forgiveness was powerful: the Prophet ﷺ had the ability to punish but chose mercy."}]},{"title":"9. Farewell Hajj and Address","blocks":[{"type":"para","text":"The Farewell Hajj and address contain important teachings about human dignity, justice, rights and responsibilities."},{"type":"bullet","text":"Study the major teachings included in the syllabus and understand their moral significance."},{"type":"bullet","text":"Think about equality, justice, respect and responsible behaviour."},{"type":"bullet","text":"Be able to explain a teaching in your own words, not just list it."},{"type":"para","text":"Think like this:For application: explain how a teaching about justice could affect how students treat classmates."}]},{"title":"10. Four outstanding qualities","blocks":[{"type":"para","text":"The syllabus specifically highlights humility, truthfulness and honesty, fulfilment of promises, and forgiveness."},{"type":"bullet","text":"Humility: do not become arrogant because of knowledge, position or success."},{"type":"bullet","text":"Truthfulness and honesty: speak truthfully and act honestly even when it is difficult."},{"type":"bullet","text":"Fulfilment of promises: keep commitments and do not make promises carelessly."},{"type":"bullet","text":"Forgiveness: control anger and forgive where appropriate."},{"type":"para","text":"Think like this:For each quality, learn one historical example and one modern-day student example. This makes application questions much easier."},{"type":"para","text":"Islamiat exam habitFor every event learn THREE things: what happened, why it mattered, and what lesson it teaches. For each quality learn the meaning plus an example."}]}]},{"title":"FINAL CCH REVISION SYSTEM","topics":[{"title":"","blocks":[{"type":"para","text":"Use this final system after finishing the notes. It is designed around the CCH emphasis on understanding and application."},{"type":"para","text":"1. First pass: read one topic and explain it aloud without looking."},{"type":"para","text":"1. Second pass: solve basic questions until the method feels automatic."},{"type":"para","text":"1. Third pass: solve mixed questions where the topic is not named. This trains you to recognise the concept."},{"type":"para","text":"1. Fourth pass: keep a 'mistake book'. Write the question type, your mistake, the correct idea and one rule that prevents the mistake."},{"type":"para","text":"1. Every few days, revise old topics before learning new ones. Spaced recall is stronger than reading the same chapter repeatedly."},{"type":"para","text":"1. Before the exam, practise without a calculator and under time pressure, especially Mathematics."}]},{"title":"The 5-question understanding test","blocks":[{"type":"bullet","text":"What is it?"},{"type":"bullet","text":"Why does it work?"},{"type":"bullet","text":"How do I recognise a question about it?"},{"type":"bullet","text":"What is the most common mistake?"},{"type":"bullet","text":"Can I explain it to a younger student in simple words?"}]},{"title":"Source note","blocks":[{"type":"para","text":"These notes are based primarily on the supplied 'CCH Syllabus New 2022' / 'CCH Revised Syllabus' documents. The supplied syllabus states that the revised entry-test syllabus applies from October 2022. Where the syllabus names a topic but does not prescribe a particular textbook explanation, the explanations in these notes are teaching-oriented expansions of that named topic, kept at the intended pre-secondary/Class 7 Cambridge level."}]}]}]

export const MASTER_NOTES_META = { title: "CCH Master Concept Notes", subtitle: "Easy-language notes for Class 8 / O-Level entry preparation", badge: "Official · Based on the CCH Revised Syllabus (Oct 2022)" } as const
